CREATE OR REPLACE FUNCTION public.fn_ouvrir_litige_rate_limited(p_mission_id UUID, p_motif TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid UUID; v_role TEXT; v_etab_id UUID; v_soignant_id UUID; v_presence_id UUID; v_recent_count INT; v_litige_id UUID; v_initie_par TEXT; BEGIN v_uid := auth.uid(); IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF; SELECT role INTO v_role FROM user_roles WHERE user_id = v_uid LIMIT 1; SELECT etablissement_id, soignant_assigne_id INTO v_etab_id, v_soignant_id FROM missions WHERE id = p_mission_id; IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF; IF v_role IN ('ETABLISSEMENT', 'ADMIN_ETABLISSEMENT') THEN IF v_etab_id != COALESCE((SELECT etablissement_id FROM user_roles WHERE user_id = v_uid LIMIT 1), v_uid) THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF; v_initie_par := 'ETABLISSEMENT'; ELSIF v_role = 'SOIGNANT' THEN IF v_soignant_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF; v_initie_par := 'SOIGNANT'; ELSIF v_role = 'ADMIN_PLATEFORME' THEN v_initie_par := 'ADMIN'; ELSE RETURN jsonb_build_object('error', 'Rôle non autorisé'); END IF; SELECT COUNT(*) INTO v_recent_count FROM litiges WHERE (etablissement_id = v_etab_id OR soignant_id = v_uid) AND cree_le > NOW() - INTERVAL '24 hours'; IF v_recent_count >= 3 THEN RETURN jsonb_build_object('error', 'Limite de 3 litiges par 24h atteinte'); END IF; IF EXISTS (SELECT 1 FROM litiges WHERE mission_id = p_mission_id AND statut NOT IN ('FERME', 'RESOLU')) THEN RETURN jsonb_build_object('error', 'Un litige est déjà ouvert pour cette mission'); END IF; SELECT id INTO v_presence_id FROM presences WHERE mission_id = p_mission_id LIMIT 1; INSERT INTO litiges (mission_id, presence_id, soignant_id, etablissement_id, motif, initie_par, statut) VALUES (p_mission_id, v_presence_id, COALESCE(v_soignant_id, v_uid), v_etab_id, p_motif, v_initie_par, 'OUVERT') RETURNING id INTO v_litige_id; RETURN jsonb_build_object('success', true, 'litige_id', v_litige_id); END; $$; GRANT EXECUTE ON FUNCTION public.fn_ouvrir_litige_rate_limited(UUID, TEXT) TO authenticated; GRANT EXECUTE ON FUNCTION public.fn_ouvrir_litige_rate_limited(UUID, TEXT) TO service_role